"""Pydantic schemas for multi-agent workflows, API payloads, and health checks."""

from typing import List, Optional
from pydantic import BaseModel, Field


# -----------------------------------------------------------------------------
# Agent Structured Output Schemas
# -----------------------------------------------------------------------------

class Plan(BaseModel):
    """Structured plan generated by the Planner Agent."""

    goal: str = Field(
        ...,
        min_length=3,
        description="The primary objective or goal extracted from the user query.",
    )
    steps: List[str] = Field(
        ...,
        min_length=1,
        description="Logical sequential steps required to accomplish the goal.",
    )


class ResearchResult(BaseModel):
    """Structured research output generated by the Research Agent."""

    findings: List[str] = Field(
        ...,
        min_length=1,
        description="Key findings and analytical points addressing each planned step.",
    )
    assumptions: List[str] = Field(
        default_factory=list,
        description="Assumptions made during analysis or research.",
    )
    unanswered_questions: List[str] = Field(
        default_factory=list,
        description="Open questions or areas requiring further investigation.",
    )


class WorkflowResponse(BaseModel):
    """Structured final answer produced by the Response Agent."""

    request_id: str = Field(
        ...,
        description="Unique identifier for the workflow execution run.",
    )
    answer: str = Field(
        ...,
        min_length=5,
        description="Synthesized, comprehensive final response addressing the query.",
    )
    key_points: List[str] = Field(
        ...,
        min_length=1,
        description="Executive summary bullet points highlighting essential takeaways.",
    )
    confidence: float = Field(
        ...,
        ge=0.0,
        le=1.0,
        description="Calibrated confidence score between 0.0 and 1.0 reflecting completeness.",
    )


# -----------------------------------------------------------------------------
# API Request / Response Schemas
# -----------------------------------------------------------------------------

class WorkflowRequest(BaseModel):
    """Request payload for initiating a workflow."""

    query: str = Field(
        ...,
        min_length=3,
        max_length=5000,
        description="The user business or technical query to process.",
        examples=["Compare the advantages and disadvantages of PostgreSQL and MongoDB for a startup SaaS application."],
    )


class WorkflowAPIResponse(BaseModel):
    """Public API response returned by the workflow endpoint."""

    request_id: str = Field(..., description="Unique workflow run request ID")
    answer: str = Field(..., description="Comprehensive answer synthesized by the agents")
    key_points: List[str] = Field(..., description="Key executive takeaways")
    confidence: float = Field(..., description="Confidence score (0.0 to 1.0)")
    errors: List[str] = Field(default_factory=list, description="Any warnings or non-fatal errors during execution")


class HealthResponse(BaseModel):
    """Health status response."""

    status: str = Field(default="healthy", description="Application service status")
    database: str = Field(default="unconfigured", description="Database connection status: connected, disconnected, or unconfigured")
    app_env: str = Field(..., description="Running environment")
    version: str = Field(default="0.1.0", description="Application version")
